(()=>{'use strict';
const E=x=>(window.esc?esc(x):String(x??'')),D=x=>(window.dateBR?dateBR(x):x),S=t=>t.status||(t.done?'completed':'pending');
function taskFilters(){if(currentTab!=='Início'||document.querySelector('.sv7Filters'))return;const root=document.getElementById('view'),tasks=(state.tasks||[]).filter(t=>S(t)!=='completed');if(!tasks.length)return;const counts={pending:tasks.filter(t=>S(t)==='pending').length,progress:tasks.filter(t=>S(t)==='progress').length,mine:tasks.filter(t=>t.assignee===me?.name).length};const bar=document.createElement('div');bar.className='sv7Filters';bar.innerHTML=`<button data-sv7-filter="all" class="on">Todas <b>${tasks.length}</b></button><button data-sv7-filter="mine">Minhas <b>${counts.mine}</b></button><button data-sv7-filter="pending">Pendentes <b>${counts.pending}</b></button><button data-sv7-filter="progress">Em andamento <b>${counts.progress}</b></button>`;const section=[...root.querySelectorAll('.section')].find(x=>/Ações|Tarefas/i.test(x.textContent));section?.insertAdjacentElement('beforebegin',bar)}
function meetingCompleteness(){if(currentTab!=='Presidência')return;document.querySelectorAll('.inlinePlan').forEach(p=>{if(p.querySelector('.sv7SaveHint'))return;const save=[...p.querySelectorAll('button')].find(b=>/Salvar ata/i.test(b.textContent));if(!save)return;const hint=document.createElement('small');hint.className='sv7SaveHint';hint.textContent='Você pode salvar a ata mesmo com informações ainda pendentes.';save.insertAdjacentElement('beforebegin',hint)})}
function filter(kind){const root=document.getElementById('view');root.querySelectorAll('.item').forEach(el=>{const t=(state.tasks||[]).find(x=>el.textContent.includes(x.title));if(!t)return;let show=S(t)!=='completed';if(kind==='mine')show=show&&t.assignee===me?.name;if(kind==='pending')show=show&&S(t)==='pending';if(kind==='progress')show=show&&S(t)==='progress';el.style.display=show?'':'none'})}
function run(){try{taskFilters();meetingCompleteness()}catch(e){console.warn('safe bundle v7 skipped',e)}}document.addEventListener('click',e=>{const b=e.target.closest('[data-sv7-filter]');if(!b)return;b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));filter(b.dataset.sv7Filter)});const old=window.renderTab;if(typeof old==='function')window.renderTab=function(){const r=old.apply(this,arguments);setTimeout(run,40);return r};new MutationObserver(()=>requestAnimationFrame(run)).observe(document.getElementById('view'),{childList:true,subtree:true});const st=document.createElement('style');st.textContent=`.sv7Filters{display:flex;gap:7px;overflow:auto;margin:-2px 0 12px;padding:2px 0;scrollbar-width:none}.sv7Filters button{border:0;background:#e9eeed;color:var(--mut);border-radius:999px;padding:8px 10px;white-space:nowrap;font-size:11px;font-weight:650}.sv7Filters button.on{background:var(--teal);color:#fff}.sv7Filters b{font-size:10px;margin-left:3px}.sv7SaveHint{display:block;margin:5px 0 9px;color:var(--mut);font-size:11px}@media(prefers-color-scheme:dark){.sv7Filters button{background:#2c2c2e}.sv7Filters button.on{background:var(--teal)}}`;document.head.appendChild(st)})();